139	    @Test public void usesOnForCheckboxValueIfNoValueSet() {
140	        Document doc = Jsoup.parse("<form><input type=checkbox checked name=foo></form>");
141	        FormElement form = (FormElement) doc.select("form").first();
142	        List<Connection.KeyVal> data = form.formData();
143	        assertEquals("on", data.get(0).value());
144	        assertEquals("foo", data.get(0).key());
145	    }
